apiChanges:
paths:
  /{code}/qr:
    get:
      summary: QR code PNG for a short link
      security: []
      parameters:
        - { name: code, in: path, required: true, schema: { type: string, pattern: '^[A-Za-z0-9_-]{4,32}$' } }
        - { name: size, in: query, required: false, schema: { type: integer, minimum: 128, maximum: 1024, default: 256 } }
      responses:
        '200': { description: QR code encoding the short URL, content: { image/png: { schema: { type: string, format: binary } } } }
        '400': { description: size out of range (type /problems/invalid-qr-size) or not an integer (type /problems/validation-failed), content: { application/problem+json: {} } }
        '404': { description: unknown or deleted link (type /problems/link-not-found), content: { application/problem+json: {} } }
        '429': { description: rate limited (type /problems/rate-limited), content: { application/problem+json: {} } }
